public class IngredientInventory {
    private final Map<Ingredient, Integer> stock = new EnumMap<>(Ingredient.class);

    // all or nothing: check everything, then deduct everything, in one lock
    public synchronized boolean tryReserve(Map<Ingredient, Integer> needs) {
        for (Map.Entry<Ingredient, Integer> e : needs.entrySet())
            if (stock.getOrDefault(e.getKey(), 0) < e.getValue())
                return false;                       // reject, nothing touched
        for (Map.Entry<Ingredient, Integer> e : needs.entrySet())
            stock.merge(e.getKey(), -e.getValue(), Integer::sum);
        return true;                                // fully reserved
    }
    public synchronized void release(Map<Ingredient, Integer> needs) {
        needs.forEach((i, u) -> stock.merge(i, u, Integer::sum));   // compensation
    }
    public synchronized void refill(Ingredient i, int units) {
        stock.merge(i, units, Integer::sum);
    }
}

