import threading
from typing import Dict


class IngredientInventory:
    def __init__(self):
        self._stock: Dict[Ingredient, int] = {}
        self._lock = threading.Lock()

    def try_reserve(self, needs: Dict[Ingredient, int]) -> bool:
        with self._lock:
            for ing, units in needs.items():
                if self._stock.get(ing, 0) < units:
                    return False
            for ing, units in needs.items():
                self._stock[ing] = self._stock.get(ing, 0) - units
            return True

    def release(self, needs: Dict[Ingredient, int]) -> None:
        with self._lock:
            for ing, units in needs.items():
                self._stock[ing] = self._stock.get(ing, 0) + units

    def refill(self, i: Ingredient, units: int) -> None:
        with self._lock:
            self._stock[i] = self._stock.get(i, 0) + units

    def level(self, i: Ingredient) -> int:
        with self._lock:
            return self._stock.get(i, 0)


class InvalidAmountException(Exception):
    def __init__(self, a: int): super().__init__(f"invalid amount {a}")


class InsufficientBalanceException(Exception):
    def __init__(self, price: int, balance: int): super().__init__(f"need {price}, have {balance}")


class IngredientUnavailableException(Exception):
    def __init__(self, needs): super().__init__(f"cannot supply {needs}")


class BrewFailureException(Exception): pass


class IdleState(MachineState):
    def insert_money(self, m, amount):
        if amount <= 0:
            raise InvalidAmountException(amount)
        m.add_balance(amount)
        m.set_state(HasMoneyState())

    def select_drink(self, m, drink_type, addons): raise RuntimeError("Insert money first")
    def dispense(self, m): raise RuntimeError("Nothing to dispense")
    def refund(self, m): raise RuntimeError("No money to refund")


class HasMoneyState(MachineState):
    def insert_money(self, m, amount): m.add_balance(amount)

    def select_drink(self, m, drink_type, addons):
        b = BaseBeverage(drink_type, m.get_book().recipe_for(drink_type))
        for a in addons:
            b = self._decorate(b, a)
        if m.get_balance() < b.cost():
            raise InsufficientBalanceException(b.cost(), m.get_balance())
        needs = b.needs()
        if not m.get_inventory().try_reserve(needs):        # atomic, all or nothing
            raise IngredientUnavailableException(needs)
        m.set_pending(b, needs)
        m.set_state(BrewingState())
        m.dispense()

    def _decorate(self, b, a):
        if a == AddOn.EXTRA_MILK: return ExtraMilk(b)
        if a == AddOn.EXTRA_SUGAR: return ExtraSugar(b)
        if a == AddOn.EXTRA_SHOT: return ExtraShot(b)
        raise ValueError(a)

    def dispense(self, m): raise RuntimeError("Select a drink first")

    def refund(self, m):
        m.refund_balance()
        m.set_state(IdleState())


class BrewingState(MachineState):
    def insert_money(self, m, amount): raise RuntimeError("Brewing")
    def select_drink(self, m, drink_type, addons): raise RuntimeError("Brewing")
    def refund(self, m): raise RuntimeError("Brewing")

    def dispense(self, m):
        try:
            m.brew_hardware()                             # pour the cup
            m.give_change(m.get_balance() - m.get_pending_cost())
        except BrewFailureException:
            m.get_inventory().release(m.get_pending_needs())   # compensation
            m.refund_balance()
        finally:
            m.reset()
            m.set_state(IdleState())

