    void insertMoney(long amt) { state_->insertMoney(*this, amt); }
    void selectDrink(DrinkType t, const std::vector<AddOn>& a) { state_->selectDrink(*this, t, a); }
    void dispense() { state_->dispense(*this); }
    void refund() { state_->refund(*this); }

    // operator facing
    void refill(Ingredient i, int units) { inventory_.refill(i, units); }

    // callbacks for states
    void setState(std::shared_ptr<MachineState> s) { state_ = std::move(s); }
    void addBalance(long a) { balance_ += a; }
    long getBalance() const { return balance_; }
    IngredientInventory& getInventory() { return inventory_; }
    RecipeBook& getBook() { return book_; }
