        pending_ = std::move(b);
        pendingNeeds_ = std::move(needs);
    }
    long getPendingCost() { return pending_->cost(); }
    std::map<Ingredient, int> getPendingNeeds() { return pendingNeeds_; }
    void brewHardware() { std::cout << "Brewing: " << pending_->description() << "\n"; }
    void giveChange(long c) { if (c > 0) std::cout << "Change: " << c << "\n"; }
    void refundBalance() { std::cout << "Refund: " << balance_ << "\n"; balance_ = 0; }
    void reset() { balance_ = 0; pending_ = nullptr; pendingNeeds_.clear(); }

private:
    std::shared_ptr<MachineState> state_;
    IngredientInventory inventory_;
    RecipeBook book_;
    long balance_ = 0;
    std::shared_ptr<Beverage> pending_;
    std::map<Ingredient, int> pendingNeeds_;
};

void IdleState::insertMoney(CoffeeMachine& m, long amount) {
    if (amount <= 0) throw InvalidAmountException(amount);
    m.addBalance(amount);
    m.setState(std::make_shared<HasMoneyState>());
}
void HasMoneyState::insertMoney(CoffeeMachine& m, long amount) { m.addBalance(amount); }
void HasMoneyState::selectDrink(CoffeeMachine& m, DrinkType type, const std::vector<AddOn>& addons) {
    std::shared_ptr<Beverage> b = std::make_shared<BaseBeverage>(type, m.getBook().recipeFor(type));
    for (AddOn a : addons) b = decorate(b, a);
    if (m.getBalance() < b->cost()) throw InsufficientBalanceException(b->cost(), m.getBalance());
    auto needs = b->needs();
    if (!m.getInventory().tryReserve(needs)) throw IngredientUnavailableException();
    m.setPending(b, needs);
    m.setState(std::make_shared<BrewingState>());
    m.dispense();
}
void HasMoneyState::refund(CoffeeMachine& m) { m.refundBalance(); m.setState(std::make_shared<IdleState>()); }

void BrewingState::dispense(CoffeeMachine& m) {
    try {
        m.brewHardware();                                  // pour the cup
        m.giveChange(m.getBalance() - m.getPendingCost());
    } catch (const BrewFailureException&) {
        m.getInventory().release(m.getPendingNeeds());      // compensation
        m.refundBalance();
    }
    m.reset();
    m.setState(std::make_shared<IdleState>());
}

